import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const codeOf = (node) =>
  node && node.type === "INSTANCE" ? node.executeTemplate().example : undefined;

const label = instance.getString("Label");
const startIcon = codeOf(instance.getInstanceSwap("Icon"));
const selected = instance.getEnum("State", {
  Default: undefined,
  Hover: undefined,
  Selected: true,
  Disabled: undefined,
});
const disabled = instance.getEnum("State", {
  Default: undefined,
  Hover: undefined,
  Selected: undefined,
  Disabled: true,
});

export default {
  id: "Multi button/Segment",
  example: instance.getBoolean("Show icon", {
    true: instance.getBoolean("Show label", {
      true: figma.code`<HvButton${attr("selected", selected)}${attr("disabled", disabled)}${startIcon ? figma.code` startIcon={${startIcon}}` : ""}>${label ?? ""}</HvButton>`,
      false: figma.code`<HvButton${attr("selected", selected)}${attr("disabled", disabled)} icon aria-label="${label ?? ""}">${startIcon ?? ""}</HvButton>`,
    }),
    false: instance.getBoolean("Show label", {
      true: figma.code`<HvButton${attr("selected", selected)}${attr("disabled", disabled)}>${label ?? ""}</HvButton>`,
      false: figma.code`<HvButton${attr("selected", selected)}${attr("disabled", disabled)} />`,
    }),
  }),
  imports: ['import { HvButton } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
